local getasset = getcustomasset or loadcustomasset or getsynasset

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ContentProvider = game:GetService("ContentProvider")

local gui = Instance.new("ScreenGui")
gui.Name = "VideoPlayer"
gui.ResetOnSpawn = false
gui.IgnoreGuiInset = true
local okParent = pcall(function() gui.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
if not okParent then gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui") end

local label = Instance.new("TextLabel")
label.AnchorPoint = Vector2.new(0.5, 0.5)
label.Position = UDim2.fromScale(0.5, 0.5)
label.Size = UDim2.fromOffset(500, 40)
label.BackgroundTransparency = 1
label.TextColor3 = Color3.new(1, 1, 1)
label.TextStrokeTransparency = 0.5
label.Font = Enum.Font.GothamMedium
label.TextSize = 16
label.TextWrapped = true
label.Text = "Menyiapkan video..."
label.Parent = gui

local function fail(msg)
    label.Text = "Error: " .. tostring(msg)
    task.delay(8, function() gui:Destroy() end)
end

-- Base64 decoder (pakai bawaan executor kalau ada, kalau tidak pakai fallback)
local nativeDecode =
    (crypt and crypt.base64decode) or
    (crypt and crypt.base64 and crypt.base64.decode) or
    (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode) or
    base64decode or base64_decode

local lut = {}
local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i = 1, #chars do lut[chars:byte(i)] = i - 1 end

local function luaDecode(s)
    local out, n = {}, 0
    local len = #s
    for i = 1, len, 4 do
        local a, b, c, d = s:byte(i, i + 3)
        local v = lut[a] * 262144 + lut[b] * 4096 + (c and c ~= 61 and lut[c] or 0) * 64 + (d and d ~= 61 and lut[d] or 0)
        n += 1
        out[n] = string.char(math.floor(v / 65536) % 256)
        if c and c ~= 61 then
            n += 1
            out[n] = string.char(math.floor(v / 256) % 256)
        end
        if d and d ~= 61 then
            n += 1
            out[n] = string.char(v % 256)
        end
    end
    return table.concat(out)
end

local function decode(s)
    if nativeDecode then
        local ok, r = pcall(nativeDecode, s)
        if ok and type(r) == "string" and #r > 0 then return r end
    end
    return luaDecode(s)
end

local function main()
    assert(writefile, "Executor tidak punya writefile")
    assert(getasset, "Executor tidak punya getcustomasset/loadcustomasset")

    if makefolder and isfolder and not isfolder(FOLDER) then makefolder(FOLDER) end

    local assets = {}
    for i = 1, TOTAL do
        local path = string.format("%s/f_%04d.jpg", FOLDER, i)
        if not (isfile and isfile(path)) then
            writefile(path, decode(DATA[i]))
        end
        assets[i] = getasset(path)
        if i % 10 == 0 then
            label.Text = ("Menyiapkan video... %d%%"):format(math.floor(i / TOTAL * 100))
            task.wait()
        end
    end
    DATA = nil

    -- Preload (dengan batas waktu supaya tidak nyangkut)
    label.Text = "Memuat gambar..."
    local preload = {}
    for i = 1, TOTAL do
        local im = Instance.new("ImageLabel")
        im.Image = assets[i]
        preload[i] = im
    end
    local done = false
    task.spawn(function()
        pcall(function() ContentProvider:PreloadAsync(preload) end)
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 5 do task.wait(0.1) end
    for _, v in ipairs(preload) do v:Destroy() end

    label:Destroy()

    local img = Instance.new("ImageLabel")
    img.AnchorPoint = Vector2.new(0.5, 0.5)
    img.Position = UDim2.fromScale(0.5, 0.5)
    img.Size = UDim2.fromOffset(SIZE, SIZE)
    img.BackgroundTransparency = 1
    img.ScaleType = Enum.ScaleType.Fit
    img.Image = assets[1]
    img.Parent = gui

    local startTime = os.clock()
    local last = 0
    local conn
    conn = RunService.RenderStepped:Connect(function()
        local idx = math.floor((os.clock() - startTime) * FPS) + 1
        if idx > TOTAL then
            if LOOP then
                startTime = os.clock()
                idx = 1
            else
                conn:Disconnect()
                gui:Destroy()
                return
            end
        end
        if idx ~= last then
            last = idx
            img.Image = assets[idx]
        end
    end)
end

local ok, err = pcall(main)
if not ok then fail(err) end
